// Tests the patched solver directly: no sampler or summary code is linked.
#include <z3++.h>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <chrono>
#include <set>
#include <sstream>
#include <regex>
void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
std::string log(z3::solver&s){return Z3_solver_get_soft_phase_log(s.ctx(),s);}
void install(z3::solver&s,z3::expr_vector const&a,bool truth,unsigned epoch,bool shared=false){std::vector<Z3_ast> aa;std::vector<unsigned>tt,gg;for(unsigned i=0;i<a.size();++i){aa.push_back(a[i]);tt.push_back(truth);gg.push_back(shared?0:i);}Z3_solver_set_soft_phases(s.ctx(),s,aa.size(),aa.data(),tt.data(),gg.data(),epoch);s.ctx().check_error();}
unsigned field(const std::string&j,const char*key){std::smatch m;std::regex r(std::string("\"")+key+"\":([0-9]+)");require(std::regex_search(j,m,r),"missing native counter");return std::stoul(m[1]);}
void emit(const char*name,z3::solver&s,const z3::expr_vector* atoms=nullptr){require(field(log(s),"applied")<=8,"native override cap exceeded");auto stats=s.statistics();unsigned conflicts=0,restarts=0;for(unsigned i=0;i<stats.size();++i)if(stats.is_uint(i)){if(stats.key(i)=="conflicts")conflicts=stats.uint_value(i);if(stats.key(i)=="restarts")restarts=stats.uint_value(i);}std::cout<<"{\"case\":\""<<name<<"\",\"solver_conflicts\":"<<conflicts<<",\"solver_restarts\":"<<restarts<<",\"hook\":"<<log(s)<<",\"final\":[";if(atoms){auto m=s.get_model();for(unsigned i=0;i<atoms->size();++i){if(i)std::cout<<',';auto x=(*atoms)[i];std::cout<<'['<<x.id()<<','<<(m.eval(x,true).is_true()?"true":"false")<<']';}}std::cout<<"]}\n";}
struct Observer: z3::user_propagator_base {Observer(z3::solver&s):user_propagator_base(&s){register_decide();}Observer(z3::context&c):user_propagator_base(c){}void push()override{}void pop(unsigned)override{}user_propagator_base*fresh(z3::context&c)override{return new Observer(c);}};
void choices(z3::solver&s,z3::expr_vector&a,unsigned n){auto &c=s.ctx();for(unsigned i=0;i<n;++i){auto x=c.bool_const(("x"+std::to_string(i)).c_str()),y=c.bool_const(("y"+std::to_string(i)).c_str());s.add(x!=y);a.push_back(x);a.push_back(y);}}
int main(){try{
 {z3::context c;z3::solver s(c,z3::solver::simple{});z3::expr_vector a(c);choices(s,a,24);s.set("phase_selection",0u);unsigned assertions=s.assertions().size();install(s,a,true,1);require(s.assertions().size()==assertions,"preference added assertions");require(s.check()==z3::sat,"cap SAT");emit("cap",s);require(field(log(s),"applied")==8,"native cap not exercised");Z3_solver_clear_soft_phases(c,s);require(log(s).find("\"installed\":0")!=std::string::npos,"clear");install(s,a,true,2,true);require(s.check()==z3::sat,"shared SAT");emit("shared_group",s);require(field(log(s),"applied")<=1,"group cap exceeded");require(s.assertions().size()==assertions,"assertions changed");}
 {z3::context c;z3::solver s(c,z3::solver::simple{});auto x=c.bool_const("x");s.add(!x);z3::expr_vector a(c);a.push_back(x);install(s,a,true,1);require(s.check()==z3::sat&&!s.get_model().eval(x).is_true(),"soft preference became hard");emit("propagation",s);a.resize(0);a.push_back(!x);install(s,a,true,2);require(s.check()==z3::sat,"negated mapping");emit("replace_sign",s);}
 {z3::context c;z3::solver s(c,z3::solver::simple{});z3::expr_vector a(c);choices(s,a,4);Observer observer(s);install(s,a,true,1);require(s.check()==z3::sat,"special SAT");emit("special",s);require(field(log(s),"applied")==0,"special interface overwritten");}
 {z3::context c;z3::solver s(c,z3::solver::simple{});auto gate=c.bool_const("gate");z3::expr_vector all(c),pref(c);pref.push_back(gate);unsigned n=4;for(unsigned i=0;i<n*(n-1);++i)all.push_back(c.bool_const(("a"+std::to_string(i)).c_str()));for(unsigned i=0;i<n;++i){z3::expr_vector row(c);for(unsigned j=0;j<n-1;++j)row.push_back(all[i*(n-1)+j]);s.add(!gate||z3::mk_or(row));}for(unsigned j=0;j<n-1;++j)for(unsigned i=0;i<n;++i)for(unsigned k=0;k<i;++k)s.add(!gate||!all[i*(n-1)+j]||!all[k*(n-1)+j]);s.set("phase_selection",0u);install(s,pref,true,1);require(s.check()==z3::sat,"abandonment should SAT");require(s.get_model().eval(gate,true).is_false(),"impossible preference retained");emit("abandonment",s);}
 for(int mode=0;mode<3;++mode){z3::context c;z3::solver s(c,z3::solver::simple{});z3::expr_vector a(c);choices(s,a,3);std::set<std::string>models;unsigned epoch=0;while(true){if(mode)install(s,a,mode==1?epoch%2:epoch%3,epoch);auto r=s.check();if(mode){emit("enumeration",s,r==z3::sat?&a:nullptr);Z3_solver_clear_soft_phases(c,s);}if(r==z3::unsat)break;require(r==z3::sat,"enumeration unknown");auto m=s.get_model();std::string key;z3::expr_vector block(c);for(auto x:a){auto v=m.eval(x,true);key+=v.is_true()?'1':'0';block.push_back(x!=v);}require(models.insert(key).second,"duplicate model");s.add(z3::mk_or(block));++epoch;}require(models.size()==8,"soft changed model set");}
 {z3::context c;z3::solver s(c,z3::solver::simple{});z3::expr_vector a(c);choices(s,a,24);s.set("rlimit",1u);install(s,a,true,1);require(s.check()==z3::unknown,"rlimit unknown expected");emit("unknown",s);Z3_solver_clear_soft_phases(c,s);require(log(s).find("\"active\":false")!=std::string::npos,"unknown clear");}
 // Unsatisfiable pigeonhole forces conflict/backtracking/restarts. Preferences
 // remain soft and all per-query caps are checked from the recorded counters.
 for(unsigned scenario=0;scenario<3;++scenario){z3::context c;z3::solver s(c,z3::solver::simple{});z3::expr_vector a(c);unsigned n=12;for(unsigned i=0;i<n;++i)for(unsigned j=0;j<n-1;++j)a.push_back(c.bool_const(("p"+std::to_string(i)+"_"+std::to_string(j)).c_str()));for(unsigned i=0;i<n;++i){z3::expr_vector row(c);for(unsigned j=0;j<n-1;++j)row.push_back(a[i*(n-1)+j]);s.add(z3::mk_or(row));}for(unsigned j=0;j<n-1;++j)for(unsigned i=0;i<n;++i)for(unsigned k=0;k<i;++k)s.add(!a[i*(n-1)+j]||!a[k*(n-1)+j]);a.resize(120);bool cancel=scenario==1;s.set("timeout",cancel?1000u:scenario==2?2000u:20u);if(scenario==2){s.set("phase_selection",0u);s.set("rlimit",100000u);}s.set("restart_strategy",0u);install(s,a,scenario!=2,1);std::thread timer;if(cancel)timer=std::thread([&]{std::this_thread::sleep_for(std::chrono::milliseconds(3));Z3_interrupt(c);});auto r=s.check();if(timer.joinable())timer.join();require(r==z3::unknown,"pigeonhole expected bounded unknown");emit(cancel?"cancel":scenario==2?"conflict_ceiling":"timeout_backtrack",s);if(scenario==2)require(field(log(s),"conflict_cap")>0,"conflict ceiling not exercised");Z3_solver_clear_soft_phases(c,s);}
 std::cout<<"{\"passed\":true}\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
